import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'

/**
 * Example Unit Tests - Part 3
 *
 * This test suite covers 3 example files with comprehensive bidirectional testing:
 * 1. assign-subflow-outputs-example.now.ts - Subflow with complex FlowObject/FlowArray outputs
 * 2. monthly-incident-report-flow.now.ts - Simple flow with scheduled trigger
 * 3. incident-severity-alert-flow.now.ts - Flow with conditions and alert actions
 *
 * Each file has:
 * - Fluent → XML tests: Verify correct XML generation from TypeScript
 * - XML → Fluent tests: Verify correct TypeScript generation from XML
 */

describe('Example Unit Tests - Part 3', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    // ============================================================================
    // TEST FILE 1: assign-subflow-outputs-example.now.ts
    // ============================================================================
    describe('File 1: assign-subflow-outputs-example - Fluent to XML', () => {
        test('Subflow with complex FlowObject and FlowArray outputs', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'assign-subflow-outputs-example.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify subflow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const subflows = merged['sys_hub_flow']
            expect(subflows.length).toBeGreaterThanOrEqual(1)

            const subflow = subflows.find((s: any) => s.name === 'Test Subflow - Complex Outputs')
            expect(subflow).toBeDefined()
            expect(subflow.type).toBe('subflow')
            expect(subflow.description).toContain('FlowObject and FlowArray outputs')

            // Verify inputs
            expect(merged['sys_hub_flow_input']).toBeDefined()
            const inputs = merged['sys_hub_flow_input']
            expect(inputs.length).toBeGreaterThan(0)

            // Verify inputData with type validation
            const inputData = inputs.find((i: any) => i.element === 'inputData')
            expect(inputData).toBeDefined()
            expect(inputData.label).toBe('Input Data')
            expect(inputData.internal_type).toBe('string')
            expect(inputData.mandatory).toBe(false)
            expect(inputData.active).toBe(true)

            // Verify outputs with complex types
            expect(merged['sys_hub_flow_output']).toBeDefined()
            const outputs = merged['sys_hub_flow_output']
            expect(outputs.length).toBeGreaterThan(0)

            // Verify userInfo FlowObject output
            const userInfo = outputs.find((o: any) => o.element === 'userInfo')
            expect(userInfo).toBeDefined()
            expect(userInfo.label).toBe('User Info')
            expect(userInfo.mandatory).toBe(false)
            expect(userInfo.active).toBe(true)
        })

        test('assignSubflowOutputs with complex object and array values', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'assign-subflow-outputs-example.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should have multiple assignSubflowOutputs calls
            const assignOutputsInstances = flowLogicInstances.filter(
                (fl: any) => fl.logic_definition === 'df4e1945c3e232002841b63b12d3ae3e'
            )
            expect(assignOutputsInstances.length).toBeGreaterThan(0)

            // Verify first instance has proper structure
            const firstAssign = assignOutputsInstances[0]
            expect(firstAssign.comment).toBeDefined()
            expect(firstAssign.values).toBeDefined()

            // Verify values can be unzipped
            const firstValues = unzipInputArray(firstAssign.values) as any
            expect(firstValues.outputsToAssign).toBeDefined()
            expect(Array.isArray(firstValues.outputsToAssign)).toBe(true)
            expect(firstValues.outputsToAssign.length).toBeGreaterThan(0)

            // Verify output structure
            const firstOutput = firstValues.outputsToAssign[0]
            expect(firstOutput.name).toBeDefined()
            expect(firstOutput.value).toBeDefined()
        })
    })

    describe('File 1: assign-subflow-outputs-example - XML to Fluent', () => {
        test('Subflow with complex outputs transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_0adce0f663574398a8091ef740687ed6.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_0adce0f663574398a8091ef740687ed6.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Subflow')
            expect(content).toContain('FlowObject')
            expect(content).toContain('FlowArray')

            // Verify subflow definition
            expect(content).toContain('Subflow(')
            expect(content).toContain("name: 'Test Subflow - Complex Outputs'")

            // Verify inputs section
            expect(content).toContain('inputs: {')
            expect(content).toContain('StringColumn')

            // Verify outputs with complex types
            expect(content).toContain('outputs: {')
            expect(content).toContain('userInfo: FlowObject(')
            expect(content).toContain('fields: {')

            // Verify assignSubflowOutputs calls
            expect(content).toContain('wfa.flowLogic.assignSubflowOutputs(')
            expect(content).toContain('_params.outputs')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 2: monthly-incident-report-flow.now.ts
    // ============================================================================
    describe('File 2: monthly-incident-report-flow - Fluent to XML', () => {
        test('Flow with scheduled trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'monthly-incident-report-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows.find((f: any) => f.name === 'Monthly Incident Report Flow')
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()

            // Verify and validate trigger
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()

            // Validate scheduled monthly trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const val = (name: string) => findInput(triggerInputs, name)?.value

            expect(val('day_of_month')).toBe(1)
            expect(val('time')).toBeDefined()
        })

        test('Action instances with lookUpRecords and createRecord validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'monthly-incident-report-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find and validate lookUpRecords action for resolved incidents
            const lookupIncidentsAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve all resolved incidents from previous month'
            )
            expect(lookupIncidentsAction).toBeDefined()

            const lookupInputsArr = unzipInputArray(lookupIncidentsAction.values)
            const lookupInputs = (name: string) => findInput(lookupInputsArr, name)?.value

            expect(lookupInputs('table')).toBe('incident')
            expect(lookupInputs('conditions')).toContain('state=6')
            expect(lookupInputs('max_results')).toBe(1000)
            expect(lookupInputs('sort_column')).toBe('resolved_at')
            expect(lookupInputs('sort_type')).toBe('sort_desc')

            // Find and validate log action with datapills
            const logAction = actionInstances.find((action: any) => action.comment === 'Log report generation start')
            expect(logAction).toBeDefined()

            const logInputsArr = unzipInputArray(logAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            // Verify log_message contains datapills in XML format {{...}}
            const logMessage = logInputs('log_message')
            expect(logMessage).toContain('Starting monthly incident report')
            // Verify datapill format: {{uuid.run_start_date_time}} where uuid is trigger reference
            expect(logMessage).toMatch(/\{\{[^}]+\.run_start_date_time\}\}/)
            // Verify it contains the trigger field reference
            expect(logMessage).toContain('run_start_date_time')

            // Find log action with Count datapill
            const logCountAction = actionInstances.find(
                (action: any) => action.comment === 'Log number of resolved incidents found'
            )
            expect(logCountAction).toBeDefined()

            const logCountInputsArr = unzipInputArray(logCountAction.values)
            const logCountInputs = (name: string) => findInput(logCountInputsArr, name)?.value

            // Verify log_message contains datapills for Count
            const logCountMessage = logCountInputs('log_message')
            // Verify datapill format for action output: {{uuid.Count}}
            expect(logCountMessage).toMatch(/\{\{[^}]+\.Count\}\}/)
            expect(logCountMessage).toContain('Count')

            // Find createRecord action with datapills in values
            const createAction = actionInstances.find(
                (action: any) => action.comment === 'Create monthly incident summary report record'
            )
            expect(createAction).toBeDefined()

            const createInputsArr = unzipInputArray(createAction.values)
            const createInputs = (name: string) => findInput(createInputsArr, name)?.value

            expect(createInputs('table_name')).toBe('task')
            // Verify values contain datapills with specific field names
            const createValues = createInputs('values')
            // Verify Count datapill from resolvedIncidents action: {{uuid.Count}}
            expect(createValues).toMatch(/\{\{[^}]+\.Count\}\}/)
            // Verify run_start_date_time datapill from trigger: {{uuid.run_start_date_time}}
            expect(createValues).toMatch(/\{\{[^}]+\.run_start_date_time\}\}/)
        })
    })

    describe('File 2: monthly-incident-report-flow - XML to Fluent', () => {
        test('Flow transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_de7f449532604daea9e618b15ded457d.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_de7f449532604daea9e618b15ded457d.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')

            // Verify flow definition
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Monthly Incident Report Flow'")

            // Verify scheduled trigger
            expect(content).toContain('trigger.scheduled')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 3: incident-severity-alert-flow.now.ts
    // ============================================================================
    describe('File 3: incident-severity-alert-flow - Fluent to XML', () => {
        test('Flow with trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'incident-severity-alert-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows.find((f: any) => f.name === 'Incident Severity Alert Flow')
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()

            // Verify and validate trigger
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()

            // Validate trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const val = (name: string) => findInput(triggerInputs, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('origin=NULL')
            expect(val('run_flow_in')).toBe('background')
        })

        test('Action instances with lookUpRecord validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'incident-severity-alert-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances (if-else for severity checks)
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Verify if condition for severity High (1)
            const ifHighSeverity = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Check if incident severity is High (1)'
            )
            expect(ifHighSeverity).toBeDefined()

            // Verify elseIf condition for severity Medium (2)
            const elseIfMediumSeverity = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Check if incident severity is Medium (2)'
            )
            expect(elseIfMediumSeverity).toBeDefined()

            // Verify forEach loops for additional assignees
            const forEachHighSeverity = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Send SMS to each additional assignee'
            )
            expect(forEachHighSeverity).toBeDefined()

            const forEachMediumSeverity = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Send SMS to each additional assignee for medium severity'
            )
            expect(forEachMediumSeverity).toBeDefined()

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find and validate log action
            const logAction = actionInstances.find(
                (action: any) => action.comment === 'Log short description of the incident created'
            )
            expect(logAction).toBeDefined()

            const logInputsArr = unzipInputArray(logAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            expect(logInputs('log_message')).toContain('Incident created with short description')

            // Find and validate lookUpRecord action for assignment group
            const lookupGroupAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve assignment group details'
            )
            expect(lookupGroupAction).toBeDefined()

            const groupInputsArr = unzipInputArray(lookupGroupAction.values)
            const groupInputs = (name: string) => findInput(groupInputsArr, name)?.value

            expect(groupInputs('table')).toBe('sys_user_group')
            expect(groupInputs('conditions')).toContain('sys_id=')

            // Validate lookUpRecord action for manager details
            const lookupManagerAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve manager details'
            )
            expect(lookupManagerAction).toBeDefined()

            const managerInputsArr = unzipInputArray(lookupManagerAction.values)
            const managerInputs = (name: string) => findInput(managerInputsArr, name)?.value

            expect(managerInputs('table')).toBe('sys_user')
            expect(managerInputs('conditions')).toContain('sys_id=')

            // Validate sendNotification action
            const sendNotificationAction = actionInstances.find(
                (action: any) => action.comment === 'Send urgent notification to assignment group manager'
            )
            expect(sendNotificationAction).toBeDefined()

            const notificationInputsArr = unzipInputArray(sendNotificationAction.values)
            const notificationInputs = (name: string) => findInput(notificationInputsArr, name)?.value

            expect(notificationInputs('table_name')).toBe('incident')
            expect(notificationInputs('notification')).toBe('high_severity_incident_manager_notification')

            // Validate sendSms actions
            const sendSmsHighAction = actionInstances.find(
                (action: any) => action.comment === 'Send SMS to additional assignee'
            )
            expect(sendSmsHighAction).toBeDefined()

            const sendSmsMediumAction = actionInstances.find(
                (action: any) => action.comment === 'Send SMS to additional assignee for medium severity'
            )
            expect(sendSmsMediumAction).toBeDefined()

            // Validate lookUpRecords action for all assignee names
            const lookupAllAssigneesAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve all assignee names for work notes'
            )
            expect(lookupAllAssigneesAction).toBeDefined()

            const allAssigneesInputsArr = unzipInputArray(lookupAllAssigneesAction.values)
            const allAssigneesInputs = (name: string) => findInput(allAssigneesInputsArr, name)?.value

            expect(allAssigneesInputs('table')).toBe('sys_user')
            expect(allAssigneesInputs('max_results')).toBe(100)
            expect(allAssigneesInputs('sort_column')).toBe('name')
            expect(allAssigneesInputs('sort_type')).toBe('sort_asc')

            // Validate updateRecord actions
            const updateWorkNotesAction = actionInstances.find(
                (action: any) => action.comment === 'Update work notes with notification details for high severity'
            )
            expect(updateWorkNotesAction).toBeDefined()

            const updateStateAction = actionInstances.find(
                (action: any) => action.comment === 'Update incident state to In Progress'
            )
            expect(updateStateAction).toBeDefined()

            const updateStateInputsArr = unzipInputArray(updateStateAction.values)
            const updateStateInputs = (name: string) => findInput(updateStateInputsArr, name)?.value

            expect(updateStateInputs('table_name')).toBe('incident')
        })
    })

    describe('File 3: incident-severity-alert-flow - XML to Fluent', () => {
        test('Flow with conditions transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_e1e41da6d198479cb4c5273856c85acf.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_e1e41da6d198479cb4c5273856c85acf.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')
            expect(content).toContain('action')

            // Verify flow definition
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Incident Severity Alert Flow'")

            // Verify trigger
            expect(content).toContain('trigger.record')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })
})
